CREATE TABLE User (
    Email VARCHAR(255),
    Password VARCHAR(255),
    User_ID INTEGER PRIMARY KEY,
    Username VARCHAR(255)
);

CREATE TABLE Area (
    Area_ID INTEGER PRIMARY KEY,
    Area_Name VARCHAR(255)
);

CREATE TABLE House_Type (
    Type_ID INTEGER PRIMARY KEY,
    Type_Name VARCHAR(255)
);

CREATE TABLE Street (
    Belongs_to_Area_ID INTEGER NOT NULL,
    Street_ID INTEGER PRIMARY KEY,
    Street_Name VARCHAR(255),
    FOREIGN KEY (Belongs_to_Area_ID) REFERENCES Area(Area_ID)
);

CREATE TABLE House (
    Belongs_to_Street_ID INTEGER NOT NULL,
    Description VARCHAR(255),
    House_ID INTEGER PRIMARY KEY,
    Price FLOAT,
    Type_ID INTEGER NOT NULL,
    FOREIGN KEY (Belongs_to_Street_ID) REFERENCES Street(Street_ID),
    FOREIGN KEY (Type_ID) REFERENCES House_Type(Type_ID)
);

CREATE TABLE Lease (
    Description VARCHAR(255),
    House_ID INTEGER NOT NULL,
    Lease_Date DATETIME,
    Price FLOAT,
    User_ID INTEGER NOT NULL,
    PRIMARY KEY (User_ID, House_ID, Lease_Date),
    FOREIGN KEY (House_ID) REFERENCES House(House_ID),
    FOREIGN KEY (User_ID) REFERENCES User(User_ID)
);
